#include <iostream>
#include <string>

// Void recursion: print message n times
void nPrintln(const std::string& message, int times) {
    if (times >= 1) {
        std::cout << message << "\n";
        nPrintln(message, times - 1); // Base case is times == 0
    }
}

// Naive recursive palindrome using substr
bool isPalindromeNaive(const std::string& s) {
    if (s.size() <= 1) {
        return true; // Base case 1
    }
    if (s.front() != s.back()) {
        return false; // Base case 2
    }
    return isPalindromeNaive(s.substr(1, s.size() - 2)); // Recursive step
}

int main() {
    std::string word = "radar";
    std::cout << "Testing nPrintln:\n";
    nPrintln("Antigravity Recursion", 2);

    std::cout << "Testing isPalindromeNaive:\n";
    std::cout << word << (isPalindromeNaive(word) ? " is a palindrome" : " is not a palindrome") << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <utility>

// Overloaded recursive helper for palindrome
bool isPalindrome(const std::string& s, int low, int high) {
    if (high <= low) {
        return true; // Base case: 0 or 1 character left
    }
    if (s[low] != s[high]) {
        return false; // Base case: mismatch
    }
    return isPalindrome(s, low + 1, high - 1); // Subproblem shrunk from both ends
}

// Wrapper function
bool isPalindrome(const std::string& s) {
    if (s.empty()) return true;
    return isPalindrome(s, 0, static_cast<int>(s.size()) - 1);
}

// Recursive helper for selection sort
void selectionSort(std::string& s, int high) {
    if (high > 0) {
        int indexOfMax = 0;
        for (int i = 1; i <= high; ++i) {
            if (s[i] > s[indexOfMax]) {
                indexOfMax = i;
            }
        }
        std::swap(s[indexOfMax], s[high]);
        selectionSort(s, high - 1);
    }
}

// Wrapper for selection sort
void selectionSort(std::string& s) {
    if (!s.empty()) {
        selectionSort(s, static_cast<int>(s.size()) - 1);
    }
}

int main() {
    std::string text = "racecar";
    std::cout << text << (isPalindrome(text) ? " is a palindrome" : " is not a palindrome") << "\n";

    std::string messy = "ghfdacb";
    selectionSort(messy);
    std::cout << "Sorted string: " << messy << "\n";
    return 0;
}
